import { Column, CreateDateColumn, Entity, Index, ManyToOne, OneToMany, PrimaryGeneratedColumn, Unique } from 'typeorm';
import { Survey } from '../surveys/survey.entity';
import { User } from '../users/user.entity';
import { Answer } from './answer.entity';

@Entity('responses')
@Unique('unique_response_per_week', ['surveyId', 'userId', 'weekStartAt'])
export class Response {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Index()
  @Column({ name: 'survey_id' })
  surveyId: string;

  @ManyToOne(() => Survey, { onDelete: 'CASCADE' })
  survey: Survey;

  @Index()
  @Column({ name: 'user_id' })
  userId: string;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  user: User;

  @Index()
  @Column({ name: 'organization_id' })
  organizationId: string;

  @Column({ name: 'week_start_at', type: 'timestamptz' })
  weekStartAt: Date;

  @OneToMany(() => Answer, (answer) => answer.response, { cascade: true })
  answers: Answer[];

  @CreateDateColumn({ name: 'submitted_at' })
  submittedAt: Date;
}

